Lemma pv_out_cases : forall bs, let r := pv_out bs in
  (exists e loc, pv_err r = Some (e, loc) /\ (e = HE_BAD_VERSION \/ e = HE_NEED_MORE)
      /\ Z.even loc = true /\ 4 <= loc /\ loc + 1 < 2^64 /\ 0 <= pv_result_cell r 0 < 2^32 /\ 0 <= pv_adv r <= 8)
