Lemma land64_mod' : forall x, Z.land x 18446744073709551615 = x mod 2^64.
Proof. intros x. change 18446744073709551615 with (Z.ones 64). rewrite Z.land_ones by lia. reflexivity. Qed.
Lemma swrap32_small : forall z, -2^31 <= z < 2^31 -> bv_swrap 32 z = z.
Proof. intros z H. apply bv_swrap_small. replace (bv_half_modulus 32) with (2^31) by (vm_compute; reflexivity). lia. Qed.

(* [comment removed for export] *)
Ltac bload H q :=
  lazymatch type of H with bytes_at _ ?mx ?it0 ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q H ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read rsegs _ it0 bs (q - it0) b (Z_to_bv 64 q) H N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Definition isl_call_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 t3 t4 t5 t6 m' (k j ver f1 : Z) (mbs tbs j4 jt : list byte),
    ms' = MS (mkR (wz ISL_RET) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz E) (wz P)
                  (wz P) (wz (verb_of (zbytes mbs))) (wz p0) (wz k) (wz (p0 + k + 1)) (wz j) (wz ver) (wz E)
                  (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz p0) (wz k) (wz (p0 + k + 1)) (wz j) s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz P_ON_REQUEST_IMPL) fc None m' (seg_rom rsegs)
    /\ munch (isl_W lo sp P E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -112)
    /\ rw_cells rsegs m' (bv_unsigned sp + -112) [CB 4 j4; C4 (wz ver); C8 (wz (p0 + k + j + 12)); CB 24 jt]
    /\ rw_cells rsegs m' (bv_unsigned sp + -72) (map C8 (isl_sv s7 s6 s5 s4 s3 s2 s1 s0 ra))
    /\ rw_cells rsegs m' P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c) (pc_hlim c) (pc_state c) f1) pad7 pad2)
    /\ (f1 = pc_f c \/ f1 = Z.lor (pc_f c) 16) /\ 0 <= f1 < 2^14
    /\ rw_cells rsegs m' IN [C8 (wz p0)]
    /\ rw_cells rsegs m' E (ErrCodeCells EC_clear)
    /\ bytes_at rsegs m' p0 bs /\ bytes_at rsegs m' p0 mbs /\ bytes_at rsegs m' (p0 + k + 1) tbs
    /\ Z.of_nat (length mbs) = k /\ Z.of_nat (length tbs) = j
    /\ HttpCat m' g /\ XStatics m'
    /\ 1 <= k /\ 1 <= j /\ p0 + k + j + 12 <= p0 + Z.of_nat (length bs) /\ (ver = 10 \/ ver = 11).

Definition isl_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => isl_ret_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m ms'
          \/ isl_call_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs g m ms'.

Lemma isl_ret_segA : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs g m ms',
