(* [comment removed for export] *)
Lemma win_sub : forall m p0 bs a n, bytes_at rsegs m p0 bs -> 0 <= a -> 0 <= n -> a + n <= Z.of_nat (length bs) ->
  bytes_at rsegs m (p0 + a) (firstn (Z.to_nat n) (skipn (Z.to_nat a) bs))
  /\ Z.of_nat (length (firstn (Z.to_nat n) (skipn (Z.to_nat a) bs))) = n.
Proof.
  intros m p0 bs a n WIN A0 N0 AN.
  destruct (win_suffix _ _ _ (p0 + a) WIN ltac:(lia)) as [W2 L2].
  replace (Z.to_nat (p0 + a - p0)) with (Z.to_nat a) in W2, L2 by lia.
  rewrite <- (firstn_skipn (Z.to_nat n) (skipn (Z.to_nat a) bs)) in W2. apply bytes_at_app in W2. destruct W2 as [W3 _].
  split; [exact W3|]. rewrite firstn_length_le; [lia|]. rewrite length_skipn. lia.
Qed.

