Definition isl_tfound_stmt : Prop :=
  forall (cc : Z) rax ra sp gp tp t0 t1 t2 a0 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 k j : Z) (bs : list byte)
    (j8 jt : list byte) (g : bool),
  isl_ctx m m1 sp (isl_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs EC_clear g ->
  rw_cells rsegs m1 (bv_unsigned sp + -112) [CB 8 j8] ->
