Local Ltac isl_open CTX PURE sp :=
  pose proof PURE as PURE0; pose proof CTX as CTX0;
  destruct CTX as (FRhi & PC & IT & EC & WIN & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & LO & IMG & QLO & QHI & PLO & PHI & ILO & IHI & ELO & EHI & DPI & DPE & DIE);
  pose proof PCOK as PCOK0; destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold isl_W, G_HTTP_CAT in *; unfold isl_sv in FRhi; cbn [map] in FRhi;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  pose proof EC as ECf; unfold ErrCodeCells, EC_clear in EC; cbn [ec_val ec_cat ec_flags] in EC;
