Lemma isl_tloop_all : forall n, TLOOP_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros j. intros until g. intros CTX LOW8 PP TMP PURE K1 J0 QB NM. exfalso. cbn [Z.of_nat] in NM. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply isl_tloop_step. exact IH.
Qed.


