Lemma isl_mloop_all : forall n, MLOOP_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros i. intros until g. intros CTX LOW8 PP TMP PURE I0 QB NM. exfalso. cbn [Z.of_nat] in NM. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply isl_mloop_step. exact IH.
Qed.


(* [comment removed for export] *)
Lemma isl_mloop0 :
  forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s6x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (j8 jt : list byte) (g : bool),
  isl_ctx m m1 sp (isl_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs EC_clear g ->
  rw_cells rsegs m1 (bv_unsigned sp + -112) [CB 8 j8] ->
  rw_cells rsegs m1 (bv_unsigned sp + -104) [C8 (wz p0)] ->
  rw_cells rsegs m1 (bv_unsigned sp + -96) [CB 24 jt] ->
  isl_pure sp P IN E lo c p0 bs ->
  p0 < p0 + Z.of_nat (length bs) ->
  evt rsegs (isl_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz E) (wz P) (wz TOK_TAB) a1 a2 a3 a4 a5 a6 a7
              (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz p0) (wz 0) s6x (wz p0) s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3a6a0) fc None m1 (seg_rom rsegs)).
Proof.
  intros rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s6x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P IN E lo c pad7 pad2 p0 bs j8 jt g CTX LOW8 PP TMP PURE QB.
  pose proof (isl_mloop_all (length bs + 1) 0 rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s6x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
                F fc m m1 P IN E lo c pad7 pad2 p0 bs j8 jt g) as ML.
  rewrite !Z.add_0_r in ML. apply ML; try assumption; lia.
Qed.

(* [comment removed for export] *)
Definition isl_segA_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (g : bool),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells rsegs m IN [C8 (wz p0)] ->
  rw_cells rsegs m E (ErrCodeCells EC_clear) ->
  bytes_at rsegs m p0 bs -> HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) ->
  isl_pure sp P IN E lo c p0 bs -> mem_inv rsegs m ->
  evt rsegs (isl_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs g m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz (p0 + Z.of_nat (length bs))) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_INNER_PARSE_START_LINE) fc None m (seg_rom rsegs)).

